1: /**
2:  * Path helpers for references that must work against the *server's* filesystem, not the
3:  * frontend's. A remote server may have a different platform and separator conventions than
4:  * this machine, so nothing here may use `node:path` or `node:url` semantics.
5:  */
6: 
7: export type ServerPathShape = 'posix' | 'windows';
8: 
9: /** Shapes: drive-letter or UNC paths are windows; everything else is posix. */
10: export function serverPathShape(path: string): ServerPathShape {
11:   if (/^[A-Za-z]:[\\/]/.test(path) || path.startsWith('\\\\')) return 'windows';
12:   return 'posix';
13: }
14: 
15: /** True when `path` is absolute under either posix or windows rules. */
16: export function isServerAbsolutePath(path: string): boolean {
17:   return path.startsWith('/') || serverPathShape(path) === 'windows';
18: }
19: 
20: function normalizeSegments(path: string): string[] {
21:   const segments = path.split(/[\\/]+/).filter((segment) => segment !== '' && segment !== '.');
22:   const out: string[] = [];
23:   for (const segment of segments) {
24:     if (segment === '..') {
25:       // Lexical resolution: a `..` past the root is dropped rather than escaping it.
26:       if (out.length > 0) out.pop();
27:       continue;
28:     }
29:     out.push(segment);
30:   }
31:   return out;
32: }
33: 
34: /** Joins `relative` onto `directory` using the server's separator conventions. */
35: export function joinServerPath(directory: string, relative: string): string {
36:   const shape = serverPathShape(directory);
37:   const drive = shape === 'windows' ? /^([A-Za-z]:)/.exec(directory)?.[1] : undefined;
38:   const uncRoot =
39:     shape === 'windows' && drive === undefined
40:       ? /^(\\\\[^\\/]+[\\/][^\\/]+)/.exec(directory)?.[1]
41:       : undefined;
42:   const root = drive ?? uncRoot;
43:   const body = root === undefined ? directory : directory.slice(root.length);
44:   // Combined normalization so `..` in `relative` pops directory segments (clamped at root).
45:   const out = normalizeSegments(`${body}/${relative}`);
46:   if (shape === 'posix') return `/${out.join('/')}`;
47:   if (uncRoot !== undefined) return `${uncRoot}\\${out.join('\\')}`;
48:   return `${root ?? 'C:'}\\${out.join('\\')}`;
49: }
50: 
51: /** Forward-slash normalized form for comparison (case-insensitive when the dir is windows). */
52: export function normalizeServerPath(path: string, shape: ServerPathShape): string {
53:   const normalized = path.replaceAll('\\', '/').replace(/^\/+/, '/');
54:   return shape === 'windows' ? normalized.toLowerCase() : normalized;
55: }
56: 
57: /** Base name (last segment) of a server path. */
58: export function baseServerPath(path: string): string {
59:   const segments = path.split(/[\\/]+/).filter((segment) => segment !== '');
60:   return segments[segments.length - 1] ?? '';
61: }
62: 
63: /**
64:  * Path of `path` relative to `directory`, forward-slash; undefined when it escapes
65:  * the project root (including same-shape absolute paths elsewhere on the server).
66:  */
67: export function relativeServerPath(directory: string, path: string): string | undefined {
68:   const shape = serverPathShape(directory);
69:   const dir = normalizeServerPath(directory, shape);
70:   const full = normalizeServerPath(path, shape);
71:   const prefix = dir.endsWith('/') ? dir : `${dir}/`;
72:   if (!full.startsWith(prefix)) return undefined;
73:   return full.slice(prefix.length);
74: }
75: 
76: /** `file://` URI for a server path, encoded per segment; correct for both shapes. */
77: export function serverFileUri(path: string): string {
78:   const shape = serverPathShape(path);
79:   const segments = normalizeSegments(path);
80:   if (shape === 'posix') {
81:     return `file:///${segments.map(encodeURIComponent).join('/')}`;
82:   }
83:   const drive = /^([A-Za-z])/.exec(path)?.[0];
84:   if (drive !== undefined) {
85:     return `file:///${drive.toUpperCase()}:/${segments
86:       .slice(1)
87:       .map(encodeURIComponent)
88:       .join('/')}`;
89:   }
90:   const [host, ...rest] = segments;
91:   if (host === undefined) return 'file:///';
92:   return `file://${encodeURIComponent(host)}/${rest.map(encodeURIComponent).join('/')}`;
93: }

