import { sanitizeTerminalText } from './sanitize-text.ts';

/** One file's change as reported by `session.diff` (structured, never re-derived). */
export type FileDiff = Readonly<{
  file: string;
  patch: string;
  additions: number;
  deletions: number;
  status: 'added' | 'deleted' | 'modified';
  /** The server truncated this patch. */
  truncated: boolean;
}>;

/** `session` covers the whole session; `turn` starts at the latest user message. */
export type DiffScope = 'session' | 'turn';

export type PatchLine = Readonly<{
  kind: 'add' | 'del' | 'hunk' | 'meta' | 'context';
  text: string;
}>;

/** Classifies unified-diff lines for colouring; text is sanitized for the terminal. */
export function patchLines(patch: string): PatchLine[] {
  const lines = patch.replace(/\r\n?/g, '\n').split('\n');
  if (lines.at(-1) === '') lines.pop();
  return lines.map((line) => {
    const text = sanitizeTerminalText(line);
    if (line.startsWith('@@')) return { kind: 'hunk', text };
    if (
      line.startsWith('+++') ||
      line.startsWith('---') ||
      line.startsWith('diff ') ||
      line.startsWith('index ') ||
      line.startsWith('\\')
    ) {
      return { kind: 'meta', text };
    }
    if (line.startsWith('+')) return { kind: 'add', text };
    if (line.startsWith('-')) return { kind: 'del', text };
    return { kind: 'context', text };
  });
}

/** `3 files · +12 −4`, or `No changes`. */
export function diffSummary(files: readonly FileDiff[]): string {
  if (files.length === 0) return 'No changes';
  const additions = files.reduce((sum, file) => sum + file.additions, 0);
  const deletions = files.reduce((sum, file) => sum + file.deletions, 0);
  return `${files.length} file${files.length === 1 ? '' : 's'} · +${additions} −${deletions}`;
}

/** The message ID a `turn` diff starts from: the latest user message. */
export function turnStart(messages: readonly { kind: string; id: string }[]): string | undefined {
  for (let index = messages.length - 1; index >= 0; index -= 1) {
    const message = messages[index];
    if (message?.kind === 'user') return message.id;
  }
  return undefined;
}

// Matches CSI, OSC (BEL or ST terminated), and other two-byte ESC sequences.
const escapeSequence =
  // eslint-disable-next-line no-control-regex -- deliberately matching terminal control bytes
  /\u001b\[[0-?]*[ -/]*[@-~]|\u001b\][^\u0007\u001b]*(?:\u0007|\u001b\\)|\u001b[@-Z\\-_]|\u009b[0-?]*[ -/]*[@-~]/g;
// C0/C1 controls except tab and newline, plus DEL.
// eslint-disable-next-line no-control-regex -- deliberately matching terminal control bytes
const controlCharacters = /[\u0000-\u0008\u000b-\u001f\u007f-\u009f]/g;
// Bidirectional overrides/isolates that can visually reorder text.
const bidiControls = /[‪-‮⁦-⁩‎‏؜]/g;

/**
 * Makes untrusted model/tool text safe to paint: removes escape sequences that could
 * move the cursor, retitle the terminal or write the clipboard, plus bidi overrides.
 */
export function sanitizeTerminalText(text: string): string {
  return text
    .replaceAll('\r\n', '\n')
    .replace(escapeSequence, '')
    .replaceAll('\r', '\n')
    .replace(controlCharacters, '')
    .replace(bidiControls, '');
}

/** First `maxLines` lines plus a count of what was cut, for capped previews. */
export function previewLines(
  text: string,
  maxLines: number,
): { lines: string[]; hiddenLines: number } {
  const lines = text.split('\n');
  if (lines.length <= maxLines) return { lines, hiddenLines: 0 };
  return { lines: lines.slice(0, maxLines), hiddenLines: lines.length - maxLines };
}

