import { classifyTool, type ToolCategory, type TranscriptMessage } from './transcript.ts';

/**
 * Execution markers: the lifecycle of one agent run, derived purely from canonical
 * messages. An Idle message terminates every segment it closes (outcome succeeded,
 * failed, interrupted); a completed Assistant message is a qualified fallback end.
 * Segments that never started (bare queued user messages) produce no marker.
 */

export type ExecutionPhase = 'running' | 'completed' | 'failed' | 'interrupted';

export type ExecutionSegment = Readonly<{
  /** Stable identifier: the user message that opened the segment. */
  id: string;
  phase: ExecutionPhase;
  startedAt: number;
  completedAt?: number;
  /** Reported wall-time actually elapsed for the run; never queue dwell. */
  durationMs?: number;
  /** Present while running: the running tool category or derived activity. */
  activity?: string;
}>;

const activityByCategory: Readonly<Record<ToolCategory, string>> = {
  read: 'Reading',
  search: 'Searching',
  edit: 'Editing',
  shell: 'Running',
  web: 'Fetching',
  delegate: 'Delegating',
  other: 'Working',
};

type SegmentState = {
  segId: string;
  userCreatedAt: number;
  assistantCreated?: number;
  assistantCompleted?: number;
  compacting: boolean;
  lastActivity?: string;
  idle?: { at: number; outcome: 'succeeded' | 'failed' | 'interrupted' };
  /** Present when the running flag says the agent is working now. */
  running: boolean;
};

function closeSegment(state: SegmentState): ExecutionSegment | undefined {
  // A concatenation of bare queued user messages never started; show nothing.
  if (state.assistantCreated === undefined && state.idle === undefined) return undefined;
  const startedAt = state.assistantCreated ?? state.userCreatedAt;
  if (state.idle !== undefined) {
    const outcome = state.idle.outcome;
    return {
      id: state.segId,
      phase: outcome === 'succeeded' ? 'completed' : outcome,
      startedAt,
      completedAt: state.idle.at,
      durationMs: Math.max(0, state.idle.at - startedAt),
    };
  }
  if (state.running) {
    return { id: state.segId, phase: 'running', startedAt, ...(state.lastActivity === undefined ? {} : { activity: state.lastActivity }) };
  }
  if (state.assistantCompleted !== undefined) {
    return {
      id: state.segId,
      phase: 'completed',
      startedAt,
      completedAt: state.assistantCompleted,
      durationMs: Math.max(0, state.assistantCompleted - startedAt),
    };
  }
  return undefined;
}

/** Segments for a whole transcript, in user-message order. */
export function executionSegments(
  messages: readonly TranscriptMessage[],
  running: boolean,
): ExecutionSegment[] {
  const segments: ExecutionSegment[] = [];
  let current: SegmentState | undefined;

  const flush = () => {
    if (current !== undefined) {
      const closed = closeSegment(current);
      if (closed !== undefined) segments.push(closed);
      current = undefined;
    }
  };

  for (const message of messages) {
    if (message.kind === 'user') {
      flush();
      current = {
        segId: message.id,
        userCreatedAt: message.createdAt,
        compacting: false,
        running: false,
      };
      continue;
    }
    if (current === undefined) continue;
    switch (message.kind) {
      case 'assistant': {
        current.assistantCreated ??= message.createdAt;
        if (message.completedAt !== undefined) {
          current.assistantCompleted = message.completedAt;
        }
        for (const part of message.parts) {
          if (part.kind === 'tool') {
            current.lastActivity = classifyTool(part.tool.name) as ToolCategory;
            break;
          }
          if (part.kind === 'reasoning' && !part.done) current.lastActivity = 'Thinking';
        }
        break;
      }
      case 'compaction':
        if (message.state === 'running') current.compacting = true;
        break;
      case 'idle':
        current.idle = { at: message.createdAt, outcome: message.outcome };
        break;
      default:
        break;
    }
  }
  if (current !== undefined) {
    current.running = running;
    if (current.compacting) current.lastActivity = 'Compacting conversation';
    else if (current.lastActivity !== undefined && current.running) {
      current.lastActivity = activityByCategory[current.lastActivity as ToolCategory] ?? 'Working';
      // Only pins "Thinking" when that is the current state; otherwise a tool category.
      const looksLikeCategory = Object.keys(activityByCategory).includes(
        current.lastActivity as string,
      );
      if (looksLikeCategory) {
        current.lastActivity = activityByCategory[current.lastActivity as ToolCategory];
      }
    }
    flush();
  }

  return segments;
}

import { classifyTool, type ToolCategory, type TranscriptMessage } from './transcript.ts';

/**
 * Execution markers: the lifecycle of one agent run, derived purely from canonical
 * messages. An Idle message terminates every segment it closes (outcome succeeded,
 * failed, interrupted); a completed Assistant message is a qualified fallback end.
 * Bare queued user messages that never started produce no marker.
 */

export type ExecutionPhase = 'running' | 'completed' | 'failed' | 'interrupted';

export type ExecutionSegment = Readonly<{
  /** Stable identifier: the user message that opened the segment. */
  id: string;
  phase: ExecutionPhase;
  startedAt: number;
  completedAt?: number;
  /** Report the wall time the run actually took; never queue dwell. */
  durationMs?: number;
  /** Present while running: a truthful activity derived from agent state. */
  activity?: string;
}>;

const activityByCategory: Readonly<Record<ToolCategory, string>> = {
  read: 'Reading',
  search: 'Searching',
  edit: 'Editing',
  shell: 'Running',
  web: 'Fetching',
  delegate: 'Delegating',
  other: 'Working',
};

type SegmentAccum = {
  segId: string;
  userCreatedAt: number;
  assistantCreated?: number;
  assistantCompleted?: number;
  toolCategory?: ToolCategory;
  reasoningOpen: boolean;
  compacting: boolean;
  idle?: { at: number; outcome: 'succeeded' | 'failed' | 'interrupted' };
};

/** One segment is the user message that opens it plus every message up to (not including) the next user message. */
export function executionSegments(
  messages: readonly TranscriptMessage[],
  running: boolean,
): ExecutionSegment[] {
  const segments: ExecutionSegment[] = [];
  let accum: SegmentAccum | undefined;

  const closeSegment = (isLast: boolean) => {
    if (accum === undefined) return;
    const mark = markersFrom(accum, isLast && running);
    if (mark !== undefined) segments.push(mark);
    accum = undefined;
  };

  for (const message of messages) {
    if (message.kind === 'user') {
      if (accum !== undefined) closeSegment(false);
      accum = {
        segId: message.id,
        userCreatedAt: message.createdAt,
        reasoningOpen: false,
        compacting: false,
      };
      continue;
    }
    if (accum === undefined) continue;
    switch (message.kind) {
      case 'assistant':
        accum.assistantCreated ??= message.createdAt;
        if (message.completedAt !== undefined) accum.assistantCompleted = message.completedAt;
        for (const part of message.parts) {
          if (part.kind === 'tool') {
            accum.toolCategory = classifyTool(part.tool.name);
            accum.reasoningOpen = false;
          } else if (part.kind === 'reasoning') {
            accum.reasoningOpen = !part.done;
          }
        }
        break;
      case 'compaction':
        if (message.state === 'running') accum.compacting = true;
        break;
      case 'idle':
        accum.idle = { at: message.createdAt, outcome: message.outcome };
        break;
      default:
        break;
    }
  }
  if (accum !== undefined) closeSegment(true);
  return segments;
}

function markersFrom(accum: SegmentAccum, running: boolean): ExecutionSegment | undefined {
  if (accum.assistantCreated === undefined && accum.idle === undefined) return undefined;
  const startedAt = accum.assistantCreated ?? accum.userCreatedAt;
  if (accum.idle !== undefined) {
    const outcome = accum.idle.outcome;
    return {
      id: accum.segId,
      phase: outcome === 'succeeded' ? 'completed' : outcome,
      startedAt,
      completedAt: accum.idle.at,
      durationMs: Math.max(0, accum.idle.at - startedAt),
    };
  }
  if (running) {
    let activity: string | undefined;
    if (accum.compacting) activity = 'Compacting conversation';
    else if (accum.reasoningOpen) activity = 'Thinking';
    else if (accum.toolCategory !== undefined)
      activity = activityByCategory[accum.toolCategory];
    return { id: accum.segId, phase: 'running', startedAt, ...(activity === undefined ? {} : { activity }) };
  }
  if (accum.assistantCompleted !== undefined) {
    return {
      id: accum.segId,
      phase: 'completed',
      startedAt,
      completedAt: accum.assistantCompleted,
      durationMs: Math.max(0, accum.assistantCompleted - startedAt),
    };
  }
  return undefined;
}

