        key,
        summary: summarizeTools(tools),
        running: run.some((group) => group.running),
        tools,
        expanded: run.some((group) => group.expanded) || options.expandedGroups.has(key),
      });
    }
    run = [];
  };
  for (const node of nodes) {
    if (node.kind === 'tool-group') {
      run.push(node);
    } else {
      flush();
      merged.push(node);
    }
  }
  flush();
  return merged;
