import { describe, expect, test } from 'bun:test';

import { executionSegments } from './execution-segment.ts';
import type { TranscriptMessage } from './transcript.ts';

const model = { providerID: 'p', modelID: 'm' };

function user(id: string, createdAt: number): TranscriptMessage {
  return { kind: 'user', id, createdAt, text: `say: ${id}`, attachments: [] };
}

function assistant(
  id: string,
  createdAt: number,
  completedAt?: number,
  error?: string,
): TranscriptMessage {
  return {
    kind: 'assistant',
    id,
    createdAt,
    ...(completedAt === undefined ? {} : { completedAt }),
    agent: 'build',
    model,
    parts: [],
    ...(error === undefined ? {} : { error }),
  };
}

function idle(id: string, createdAt: number, outcome: 'succeeded' | 'failed' | 'interrupted'): TranscriptMessage {
  return { kind: 'idle', id, createdAt, outcome };
}

describe('executionSegments', () => {
  test('a bare queued user message produces no marker', () => {
    expect(executionSegments([user('u', 10)], false)).toEqual([]);
  });

  test('a completed segment reports wall time and completion, with the user message as id', () => {
    const segments = executionSegments(
      [user('u1', 100), assistant('a', 110, 220), idle('i', 230, 'succeeded')],
      false,
    );
    expect(segments).toEqual([
      {
        id: 'u1',
        phase: 'completed',
        startedAt: 110,
        completedAt: 230,
        durationMs: 120,
      },
    ]);
  });

  test('two sequential completed segments keep their own identities and durations', () => {
    const segments = executionSegments(
      [
        user('u1', 100),
        assistant('a1', 110, 130),
        idle('i1', 140, 'succeeded'),
        user('u2', 200),
        assistant('a2', 210, 240),
        idle('i2', 250, 'interrupted'),
      ],
      false,
    );
    expect(segments.map((segment) => [segment.id, segment.phase, segment.durationMs])).toEqual([
      ['u1', 'completed', 30],
      ['u2', 'interrupted', 40],
    ]);
  });

  test('an interrupted or failed outcome comes from idle', () => {
    const segments = executionSegments(
      [user('u', 10), assistant('a', 11, 25), idle('i', 50, 'interrupted')],
      false,
    );
    expect(segments[0]?.phase).toBe('interrupted');
    expect(segments[0]?.completedAt).toBe(50);
  });

  test('the running segment is only the last one, and reports truthfully that it never started', () => {
    const segments = executionSegments(
      [user('u1', 10), assistant('a1', 11, 12), idle('i', 13, 'succeeded'), user('u2', 20)],
      true,
    );
    // u2 never started, so no second marker appears; the first completed marker stays.
    expect(segments.map((segment) => segment.id)).toEqual(['u1']);
  });

  test('a running segment reports the tool category as its activity', () => {
    const segments = executionSegments(
      [
        user('u', 10),
        {
          kind: 'assistant',
          id: 'a',
          createdAt: 11,
          agent: 'build',
          model,
          parts: [
            {
              kind: 'tool',
              tool: { id: 't', name: 'grep', status: 'running', input: {}, startedAt: 12 },
            },
          ],
        },
      ],
      true,
    );
    expect(segments).toEqual([
      { id: 'u', phase: 'running', startedAt: 11, activity: 'Searching' },
    ]);
  });

  test('a running compaction reports the compaction phase', () => {
    const segments = executionSegments(
      [user('u', 10), { kind: 'compaction', id: 'c', createdAt: 12, state: 'running' }],
      true,
    );
    expect(segments).toEqual([
      { id: 'u', phase: 'running', startedAt: 10, activity: 'Compacting conversation' },
    ]);
  });

  test('a compaction-completed segment falls back to its underlying agent activity', () => {
    const segments = executionSegments(
      [
        user('u', 10),
        {
          kind: 'assistant',
          id: 'a',
          createdAt: 11,
          agent: 'build',
          model,
          parts: [{ kind: 'reasoning', text: 'hmm', done: false }],
        },
        { kind: 'compaction', id: 'c', createdAt: 20, state: 'completed' },
      ],
      true,
    );
    expect(segments[0]?.activity).toBe('Thinking');
  });

  test('an assistant-completed segment without idle yields a qualified completion', () => {
