import type { Theme } from './theme.ts';

const maxItems = 3;

/**
 * Server-confirmed pending user follow-ups, rendered in the conversation activity region
 * immediately above the active task marker. FIFO order; the oldest pending item maps to
 * the send-now hint. Read-only: no clickable chrome, a single keyboard action owns it.
 */
export function QueuedPreview(props: {
  items: readonly QueuedInput[];
  theme: Theme;
  width: number;
}) {
  const text = (item: QueuedInput) => {
    const single = item.text.split('\n')[0] ?? '';
    const clipped = item.text.includes('\n') ? `${single}…` : single;
    return truncateToWidth(sanitizeText(clipped), Math.max(8, props.width - 6));
  };
  const overflow = () => Math.max(0, props.items.length - maxItems);
  const shown = () => props.items.slice(0, maxItems);
  return (
    <box flexDirection="column" flexShrink={0}>
      <For each={shown()}>
        {(item, index) => (
          <box flexDirection="column">
            <text fg={props.theme.accent}>{`  ❯ ${text(item)}`}</text>
            <Show when={index() === 0}>
              <text fg={props.theme.dim}>{'    ⤷ Alt+Enter: send now'}</text>
            </Show>
          </box>
        )}
      </For>
      <Show when={overflow() > 0}>
        <text fg={props.theme.dim}>{`    … and ${overflow()} more queued`}</text>
      </Show>
    </box>
  );
}

