        { kind: 'user', id: 'm2', createdAt: 5, text: 'first follow-up', attachments: [] },
        { kind: 'user', id: 'm3', createdAt: 6, text: 'second follow-up,\nmultiline note', attachments: [] },
      ],
    };
    controller.openSession('ses_a');
