describe('grouped activity (issue #23)', () => {
  function groupedBackend(): FakeBackend {
    const backend = backendWithSession();
    const bash = (id: string) => ({
      kind: 'tool' as const,
      tool: {
        id,
        name: 'bash',
        status: 'completed' as const,
        input: { command: `bun run ${id}`, filePath: `${id}.log` },
        startedAt: 2,
        completedAt: 3,
      },
    });
    const edit = (id: string, filePath: string, status: 'completed' | 'error' = 'completed') => ({
      kind: 'tool' as const,
      tool: {
        id,
        name: 'edit',
        status,
        input: { filePath },
        startedAt: 2,
        completedAt: 3,
        ...(status === 'error' ? { error: 'exit 1' } : {}),
      },
    });
    const model = { providerID: 'opencode', modelID: 'longcat' };
    backend.messages = {
      ses_a: [
        { kind: 'user', id: 'm1', createdAt: 1, text: 'rewrite the renderer', attachments: [] },
        {
          kind: 'assistant',
          id: 'mA',
          createdAt: 2,
          agent: 'build',
          model,
          parts: [
            ...Array.from({ length: 10 }, (_, index) => bash(`s${index}`)),
            { kind: 'text', text: 'Running the build.' },
            { kind: 'tool', tool: { id: 'read1', name: 'read', status: 'completed', input: { filePath: 'a.ts' }, startedAt: 3, completedAt: 4 } },
            { kind: 'tool', tool: { id: 'read2', name: 'read', status: 'completed', input: { filePath: 'b.ts' }, startedAt: 3, completedAt: 4 } },
          ],
        },
        {
          kind: 'assistant',
          id: 'mB',
          createdAt: 5,
          agent: 'build',
          model,
          parts: [
            ...Array.from({ length: 6 }, (_, index) => edit(`e${index}`, 'src/index.ts')),
            bash('s10'),
          ],
        },
        {
          kind: 'assistant',
          id: 'mC',
          createdAt: 6,
          agent: 'build',
          model,
          parts: [edit('eFailed', 'src/fixed.ts', 'error')],
        },
        {
          kind: 'assistant',
          id: 'mD',
          createdAt: 7,
          completedAt: 8,
          agent: 'build',
          model,
          parts: [
            { kind: 'text', text: 'The rewrite is complete: tests are green and the diff is ready.' },
          ],
        },
      ],
    };
    return backend;
  }

  test('compact frame shows a few grouped rows, the visible failure and the final reply', async () => {
    const { controller, setup } = await mount(groupedBackend());
    controller.openSession('ses_a');
    await settle(setup);
    const frame = setup.captureCharFrame();

    expect(frame).toContain('Ran 11 shell commands');
    expect(frame).toContain('edited 6 files');
    // The lone failure stays visible with its error; its name is not folded away.
