            </For>
          </box>
        )}
      </Show>
      <Show
        when={(shown()?.tasks.length ?? 0) > 0}
        fallback={
          <text fg={props.theme.dim}>No plan. /plan step one; step two · or /plan propose</text>
        }
      >
        <For each={shown()?.tasks ?? []}>
