    }
    this.setState('goalSync', sessionID, { revision: result.revision, status: 'synced' });
    await this.changeGoal(
      (doc) => setSync(doc, false),
      'Shared instruction revoked after reconnect',
      sessionID,
    );
    this.clearGoalSync(sessionID);
  }
}

